      LessonBlock.example("The book on the table belongs to me.", note: "On table aur book ka rishta jor raha hai. Ye preposition hai."),
      LessonBlock.example("He is a fast runner, and he also runs fast.", note: "Pehla fast adjective hai, runner ki khoobi. Doosra fast adverb hai, runs ke tareeqe ki khoobi."),
